/* Two independent 30-day spend categories; eligibility uses the highest reached tier. */
const baseUpdate=update;
const routeLabels={branding:['0','60jt','150jt','1,5M','3M'],gmv:['0','20jt','50jt','500jt','1M']};
function refreshPresetLabels(){const values=spendThresholds[activeRoute],labels=routeLabels[activeRoute],routeName=activeRoute==='branding'?'Branding':'GMV Max';document.querySelectorAll('[data-budget-preset]').forEach((btn,i)=>{btn.dataset.budgetPreset=String(values[i]);btn.querySelector('.point-caption').textContent=labels[i];btn.setAttribute('aria-label',`Coba Level ${i+1}: Branding Rp${spendThresholds.branding[i].toLocaleString('id-ID')} atau GMV Max Rp${spendThresholds.gmv[i].toLocaleString('id-ID')} dalam 30 hari terakhir`)});const hint=document.querySelector('#scenario-route');if(hint)hint.textContent=`Titik mengatur spending ${routeName} · jt = juta, M = miliar`}
update=function(value,format=true){baseUpdate(value,format);const values=getSpends(),level=getQualifiedLevel(values);document.querySelectorAll('[data-budget-preset]').forEach((btn,i)=>{const active=i===level-1;btn.classList.toggle('is-active',active);btn.setAttribute('aria-pressed',String(active))});const card=document.querySelector('.gauge-wrap');card.dataset.level=String(level);const requirement=document.querySelector('#level-requirement');if(requirement)requirement.textContent=level===1?'Minimum Level 1: Rp0':'Minimum Level '+level+': Branding Rp'+spendThresholds.branding[level-1].toLocaleString('id-ID')+' atau GMV Max Rp'+spendThresholds.gmv[level-1].toLocaleString('id-ID');const qualifier=document.querySelector('#qualifier-info');if(qualifier){const categoryLevel=(route,value)=>{let tier=1;spendThresholds[route].forEach((threshold,i)=>{if(value>=threshold)tier=i+1});return tier},brandLevel=categoryLevel('branding',values.branding),gmvLevel=categoryLevel('gmv',values.gmv);qualifier.textContent=level===1?'Level 1 tersedia mulai Rp0.':brandLevel===gmvLevel?`Kedua kategori memenuhi Level ${level}.`:`Level ${level} mengikuti ${brandLevel>gmvLevel?'Branding':'GMV Max'} sebagai kategori tertinggi.`;}const remaining=document.querySelector('#remaining-budget');if(remaining){if(level===5)remaining.textContent='Kamu sudah di level tertinggi';else{const brand=Math.max(0,spendThresholds.branding[level]-values.branding),gmv=Math.max(0,spendThresholds.gmv[level]-values.gmv);remaining.textContent=`Branding tambah Rp${brand.toLocaleString('id-ID')} atau GMV Max tambah Rp${gmv.toLocaleString('id-ID')}`}}};
function revealCurrent(){const item=document.querySelector('.level-section.is-current');if(item)item.open=true}
document.addEventListener('click',e=>{const route=e.target.closest('[data-spend-route]'),preset=e.target.closest('[data-budget-preset]'),delta=e.target.closest('[data-budget-delta]');if(route){setActiveRoute(route.dataset.spendRoute);refreshPresetLabels();update(Number(budget.value.replace(/\D/g,''))||0);return}if(preset||delta){if(preset){const index=[...document.querySelectorAll('[data-budget-preset]')].indexOf(preset);spendFields.branding.value=spendThresholds.branding[index].toLocaleString('id-ID');spendFields.gmv.value=spendThresholds.gmv[index].toLocaleString('id-ID');update(Number(budget.value.replace(/\D/g,''))||0);}else{const current=Number(budget.value.replace(/\D/g,''))||0;update(Math.max(0,current+Number(delta.dataset.budgetDelta)));}revealCurrent();const card=document.querySelector('.gauge-wrap');card.classList.remove('budget-pulse');void card.offsetWidth;card.classList.add('budget-pulse');return}const more=e.target.closest('.faq-more');if(more){const extra=document.querySelector('.faq-extra'),willOpen=extra.hidden;extra.hidden=!willOpen;more.setAttribute('aria-expanded',String(willOpen));more.innerHTML=willOpen?'Tampilkan pertanyaan utama <span>↑</span>':'Lihat semua pertanyaan <span>↓</span>'}});
document.querySelectorAll('.faq-item').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)document.querySelectorAll('.faq-item').forEach(other=>{if(other!==item)other.open=false})}));
refreshPresetLabels();update(Number(budget.value.replace(/\D/g,''))||0);
const levelMap=document.querySelector('.map-points');levelMap?.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;const items=[...levelMap.querySelectorAll('[data-budget-preset]')],i=items.indexOf(document.activeElement);if(i<0)return;e.preventDefault();items[(i+(e.key==='ArrowRight'?1:-1)+items.length)%items.length].focus()});
